head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screnId = "ULDBNS04000"; // 화면ID(업무공통 SCREN_ID 전달용 — fn_SetMktactCd 에서 프로그램 ID 기준 재설정)
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "1";
scwin.vRowCount = 0;
scwin.processGp = "";
scwin.fn_GetPar = null;
scwin.vProcsStatCd = "";
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.fnListSyncUrl = "";
scwin.fnDtlSyncUrl = "";
scwin.fnAcptUrl = "";
scwin.fnModifyUrl = "";
scwin.fnProcComplt = "";
scwin.fnTeamLeaderConfirmUrl = "";
scwin.fnExcelDownUrl = "";
scwin.arrPar = [];
scwin.vSelObj = null; // 발행기관 팝업 결과를 받을 대상 컴포넌트
scwin.jobtitl = "";
scwin.duty = "";
scwin.dutyChrg = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description /////// 2. 초기화 영역 /////////
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 세션 사용자 정보 보관, 버튼·항목 숨김, 탭 초기 선택, 콤보·시장조치구분 설정 후 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.empNo = $c.session.getUserInfo("empNo");   // 사원번호
    scwin.empNm = $c.session.getUserInfo("empNm");   // 사용자이름
    scwin.jobtitl = $c.session.getUserInfo("jobtitl"); // 패널라운드처리(신청)
    scwin.duty = $c.session.getUserInfo("duty"); // 패널라운드처리(상세)
    scwin.dutyChrg = $c.session.getUserInfo("dutyChrg"); // 패널라운드처리(접수)

    // 숨기기
    lbl_ReturnPos.hide();
    btn_StdCdReq.hide();
    txb_Dtl1.hide();
    btn_Search2.hide();
    btn_ApprovFileCreat.hide();
    btn_ProcsComplt.hide();
    btn_Update.hide();
    btn_TeamleadrConfrm.hide();
    btn_AcptRet.hide();

    scwin.chgStatComp();

    btn_Excel.hide();
    grd_Grid_excel.hide();
    grd_DataVf.hide();

    // showload.hide(); // showload.style.display = "none";

    txb_sriBndApplTpCd.hide();
    txb_sriBndTpCd.hide();
    txb_sriBndRcptYn.hide();
    txb_FrnBasIntTpCd2.hide();

    // 행사종료일 숨기기 JACKAL_190726
    // fn_option_exer_Init();

    // 탭지정 - 신청내역
    tab_List.setSelectedTabIndex(0);
    tab_Detail.setSelectedTabIndex(0);
    tab_SecutizAsst.setSelectedTabIndex(0);

    // 콤보설정
    await scwin.setComboCode();

    // 시장조치구분 설정
    scwin.setMktactCd();

    // 탭설정
    // scwin.setDtlTab();

    // 목록조회
    await scwin.listSync();

    // 임시데이터셋설정

    // dts_Temp.insertRow(); - 추후 추가하기
    txb_BndTpNm.setStyle("backgroundColor", "#FFFFFF");
    cmb_BndIntPayDdBasTpCd.setStyle("backgroundColor", "#FFFFFF");
    cmb_IntMmendTpCd.setStyle("backgroundColor", "#FFFFFF");

    // 데이터검증 버튼 초기화 - 회사채인경우만 보임.
    if (scwin.vMktactCd === "141") {
        btn_data_vf.show('');
    } else {
        btn_data_vf.hide();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dlt_bndOptionCall_onrowpositionchange
 * @description /////// 3. 컴포넌트 이벤트 영역 /////////
 * @param {Object} info info
 * @returns {void}
 * @hidden N
 */
scwin.dlt_bndOptionCall_onrowpositionchange = function (info) {
    try {
        let row = info.newRowIndex;
        if (row > -1) {
            if (dlt_bndOptionCall.getCellData(row, 'callExerStrtDd') !== '' && dlt_bndOptionCall.getCellData(row, 'callExerEndDd') !== '') {
                scwin.chkCall();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.dlt_bndOptionCall_onrowpositionchange" });
    }
};

/**
 * @method
 * @name dlt_bndOptionPut_onrowpositionchange
 * @description 풋옵션 목록 행 위치 변경 — 선택 행 기준 화면 반영
 * @param {Object} info info
 * @returns {void}
 * @hidden N
 */
scwin.dlt_bndOptionPut_onrowpositionchange = function (info) {
    try {
        let row = info.newRowIndex;
        if (row > -1) {
            if (dlt_bndOptionPut.getCellData(row, 'putExerStrtDd') !== '' && dlt_bndOptionPut.getCellData(row, 'putExerEndDd') !== '') {
                scwin.chkPut();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.dlt_bndOptionPut_onrowpositionchange" });
    }
};

/**
 * @method
