 * @description img_BndTpNm 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_BndTpNm_onclick = async function () {
    try {
        scwin.getBndClss();
        const url = "/ui/bns/bnscommon/ULDBNS90002.xml";
        const options = {
            id: "ULDBNS90002",
            popupName: "채권분류코드 검색",
            frameModal: "top",
            width: 600,
            height: 500,
        };
        const rtn = await $c.win.openPopup(url, options, scwin.arrPar);
        scwin.setBndClss(rtn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.img_BndTpNm_onclick" });
    }
};

