/**
 * @method
 * @name btn_AcptRet_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_AcptRet_onclick = async function () {
    try {
        if (dlt_searchList.getRowCount() === 0) return;
        if (await $c.bns.checkModAndRet(scwin.vBndApplId) > 0) return;
        scwin.processGp = '2';
        scwin.getReturn();
        const url = "/ui/bns/bnscommon/ULDBNS90004.xml";

        const options = {
            id: "ULDBNS90004",
            popupName: "반송처리",
            frameModal: "top",
            width: 600,
            height: 500,
        };
        let rtn = await $c.win.openPopup(url, options, scwin.arrPar);

        await scwin.setReturn(rtn);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.btn_AcptRet_onclick" });
    }
};

