/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 「팀장확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function () {
    try {
        scwin.processGp = "6";

        // 체크된 것 카운팅
        let nTrueCnt = 0;
        let arr = [];

        dlt_chkConfirmList.removeAll();

        for (let nRow = 0; nRow < dlt_searchList.getRowCount(); nRow++) {
            if (grd_AcptList.getCellChecked(nRow, "CHK")) {
                nTrueCnt++;

                // 체크된 데이터만 다시 담아서 넘기기
                let obj = {};
                obj.chk = dlt_searchList.getDataRow(nRow).CHK;
                obj.bndApplId = dlt_searchList.getDataRow(nRow).bndApplId;
                obj.bndListProcsTpCd = dlt_searchList.getDataRow(nRow).bndListProcsTpCd;
                obj.strtDd = dlt_searchList.getDataRow(nRow).strtDd;
                obj.isuCd = dlt_searchList.getDataRow(nRow).isuCd;
                obj.empNo = scwin.empNo;
                obj.teamleadrNm = scwin.empNm;

                arr.push(obj);
                // console.log(JSON.stringify(arr));
            }
        }

        dlt_chkConfirmList.setJSON(arr, true);

        // 고객요건에의한 체크 추가. 2024-06-05 by김효준
        if (await $c.bns.addCheck(dma_bndIsu) > 0) return;
        await scwin.teamleadrConfrmAll(scwin.screnId, "", "", scwin.vBndListProcsTpCd, nTrueCnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.btn_TeamleadrConfrm_onclick" });
    }
};

