/**
 * @method
 * @name txb_UnqIsuEngNm_onkeyup
 * @description txb_UnqIsuEngNm 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_UnqIsuEngNm_onkeyup = function () {
    try {
        let pattern = /^[ㄱ-ㅎ|ㅏ-ㅣ|가-힣]/;
        let str = txb_UnqIsuEngNm.getValue() + ' ';
        for (let i = 0; i < str.length - 1; i++) {
            if (pattern.test(str.substring(i, i + 1))) {
                $c.win.alert('한글은 사용할 수 없습니다');
                txb_UnqIsuEngNm.setValue(str.substring(0, str.length - 2));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.txb_UnqIsuEngNm_onkeyup" });
    }
};

/**
 * @method
 * @name cmb_AsstSecutizTpCd_onselchange2
 * @description 자산유동화구분 콤보 선택 변경 처리(레거시 OnSelChange2 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_AsstSecutizTpCd_onselchange2 = function () {
    try {
        if (scwin.vBndListProcsTpCd === '1') return;
        cmb_SfValuYn1.setDisabled(false);
        cmb_SfValuYn2.setDisabled(false);
        cmb_SfValuYn3.setDisabled(false);
        cmb_SfValuYn4.setDisabled(false);
        if (cmb_AsstSecutizTpCd.getValue() !== '') {
            if (cmb_CreditValuInstCd1.getValue() !== '') {
                cmb_SfValuYn1.setValue('Y');
            }
            if (cmb_CreditValuInstCd2.getValue() !== '') {
                cmb_SfValuYn2.setValue('Y');
            }
            if (cmb_CreditValuInstCd3.getValue() !== '') {
                cmb_SfValuYn3.setValue('Y');
            }
            if (cmb_CreditValuInstCd4.getValue() !== '') {
                cmb_SfValuYn4.setValue('Y');
            }
        } else {
            cmb_SfValuYn1.setValue('');
            cmb_SfValuYn2.setValue('');
            cmb_SfValuYn3.setValue('');
            cmb_SfValuYn4.setValue('');
            cmb_SfValuYn1.setDisabled(true);
            cmb_SfValuYn2.setDisabled(true);
            cmb_SfValuYn3.setDisabled(true);
            cmb_SfValuYn4.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.cmb_AsstSecutizTpCd_onselchange2" });
    }
};

