        // ELB/DLB 일 경우 옵션설정
        if (cmb_NusualBndTpCd.getValue() === '3' ||
            cmb_NusualBndTpCd.getValue() === '4') {
            let cd = '';
            if (cmb_RghtTpCd.getValue() === 'C') cd = '1';

