            else if (cmb_RghtTpCd.getValue() === 'A') cd = '3';
            cmb_ImbdoptCorpbndCd.setValue(cd);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.cmb_NusualBndTpCd_onkillfocus" });
    }
};

