/**
 * @method
 * @name cmb_ExerPrcAdjMktprcDnYn_onselchange2
 * @description 행사가격조정 시가하락여부 콤보 선택 변경 처리(레거시 OnSelChange2 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ExerPrcAdjMktprcDnYn_onselchange2 = function () {
    try {
        // alert('cmb_ExerPrcAdjMktprcDnYn.OnSelChange2()');
        let cd = cmb_ExerPrcAdjMktprcDnYn.getValue();
        // 행사가격 조정 해당사항이면
        if (cd === 'Y') {
            // 주식관련 행사가격 조정 설정변경
            // cmb_ExerPrcAdjMktprcDnYn.Enable2 = true;
            cmb_StkcertMmendTpCd.setDisabled(false);
            edt_FstExerPrcAdjDd.setDisabled(false);
            edt_ExerPrcAdjCycle.setDisabled(false);
            edt_ExerPrcAdjCnt.setDisabled(false);
            edt_FstExerPrcAdjDd.show('');
            btn_AddExerPrc.show('');
            btn_DelExerPrc.show('');
            btn_StockRelAutoInput.show('');
        } else {
            // cmb_ExerPrcAdjMktprcDnYn.Enable2 = false;
            cmb_StkcertMmendTpCd.setDisabled(true);
            edt_FstExerPrcAdjDd.setDisabled(true);
            edt_ExerPrcAdjCycle.setDisabled(true);
            edt_ExerPrcAdjCnt.setDisabled(true);
            edt_FstExerPrcAdjDd.hide();
            btn_AddExerPrc.hide();
            btn_DelExerPrc.hide();
            btn_StockRelAutoInput.hide();
            cmb_StkcertMmendTpCd.setValue('');
            edt_FstExerPrcAdjDd.setValue('');
            edt_ExerPrcAdjCycle.setValue('');
            edt_ExerPrcAdjCnt.setValue('');
            dlt_bndStockRelExecprcAdj.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.cmb_ExerPrcAdjMktprcDnYn_onselchange2" });
    }
};

/**
 * @method
 * @name btn_ChgIntRtAutoInsert_onclick
 * @description 「자동입력」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ChgIntRtAutoInsert_onclick = async function () {
    try {
        let cd = cmb_IntDecsnRegulYn.getValue();

        // 상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
        if (cmb_RedmptMethdTpCd.getValue() === "3") {
            // 금리결정 정기이면
            if (cd === 'Y') {
                $c.win.alert("상환방법이 영구채 일 경우 금리결정정기여부를 비정기로 선택하여야 합니다.");
                return;
            }
        }

        // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
        let vIntDecsnBasDys = edt_IntDecsnBasDys.getValue();
        if (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1) {
            $c.win.alert('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.');
            return;
        }

        // 변동금리 자동입력 JACKAL_190509
        await scwin.chgIntRtAutoInput();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.btn_ChgIntRtAutoInsert_onclick" });
    }
};

