 * @description 기준금리상세2 콤보 데이터 필터 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row row
 * @returns {Boolean}
 * @hidden N
 */
scwin.dlt_frnBasIntTpCd2_OnFilter = function (row) {
    try {
        let frnBasIntTpCd1 = cmb_FrnBasIntTpCd1.getValue();
        if (dlt_frnBasIntTpCd2.getCellData(row, "value").substr(0, 1) === frnBasIntTpCd1) {
            return true;
        } else {
            return false;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.dlt_frnBasIntTpCd2_OnFilter" });
    }
};

