            // let xls_path = "c:\\staffDownload\\회사채데이터검증_" + today + ".xlsx"; //파일형식 today_화면명.xls
            $c.data.downloadGridViewExcel(grd_DataVf, { fileName : fileNm, maxRowCount : "8" });
        } else {
            $c.win.alert("데이터가 없습니다.");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS04000.dts_DataVf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name tab_List_ontabclick
 * @description tab_List 탭 클릭 이벤트
 * @param {String} tabId tabId
 * @param {Number} index index
 * @returns {Promise<void>}
