 */
scwin.tab_List_ontabclick = async function (tabId, index) {
    try {
        scwin.vRowCount = 0;
        scwin.clearIsuInfo();
        scwin.vBndListProcsTpCd = String(index + 1);
        txb_Dtl1.hide();
        txb_Dtl.show('');
        if (scwin.vBndListProcsTpCd === '2') {
            txb_Dtl.setValue("접수내역");
            txb_BndTpNm.setStyle('backgroundColor', "#ffff99");
            cmb_BndIntPayDdBasTpCd.setStyle('backgroundColor', "#ffff99");
            cmb_IntMmendTpCd.setStyle('backgroundColor', "#ffff99");
            btn_Excel.show('');

            btn_Search2.show();
            btn_ApprovFileCreat.show();
            btn_ProcsComplt.show();
            btn_Update.show();
            btn_TeamleadrConfrm.show();
            btn_AcptRet.show();

            btn_Search.hide();
            btn_Acpt.hide();
            btn_ApplRet.hide();

            // 데이터검증 버튼 안보이게.
            btn_data_vf.hide();
        } else {
            txb_Dtl.setValue("신청내역");
            txb_BndTpNm.setStyle('backgroundColor', "#ffffff");
            cmb_BndIntPayDdBasTpCd.setStyle('backgroundColor', "#ffffff");
            cmb_IntMmendTpCd.setStyle('backgroundColor', "#ffffff");
            btn_Excel.hide();

            btn_Search.show();
            btn_Acpt.show();
            btn_ApplRet.show();

            btn_Search2.hide();
            btn_ApprovFileCreat.hide();
            btn_ProcsComplt.hide();
            btn_Update.hide();
            btn_TeamleadrConfrm.hide();
            btn_AcptRet.hide();

            // 데이터검증 버튼 초기화 - 회사채인경우만 보임.
            if (scwin.vMktactCd === "141") {
                btn_data_vf.show('');
            }
        }
        scwin.chgStatComp();
        //  국채인 경우만 발행전국채거래구분코드 수정가능  jackal_150127
        scwin.presaleGovbndTrdTpCd();
        await scwin.listSync();
        scwin.setDtlTab();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS04000.tab_List_ontabclick" });
    }
};

