/**
 * @method
 * @name listSync
 * @description 신청/접수 목록을 조회한다.
 * @param {Number} rowIndex rowIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function (rowIndex) {
    if (rowIndex === "" || rowIndex === undefined) {
        rowIndex = 0;
    }
    scwin.vRowPos = rowIndex;
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd);
    dma_search.set("vMktactCd", scwin.vMktactCd);

    const sbmOptions = {
        id: "sbm_searchList",
        action: scwin.fnListSyncUrl,
        method: "get",
        ref: "dma_search=body",
        target: "dlt_searchList=body",
        gridview: "grd_ApplList,grd_AcptList",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_searchList_submitdone(sbmRtn);

    if (scwin.vBndListProcsTpCd === '1') {
        grd_ApplList.show('');
    } else {
        grd_AcptList.show('');
    }
};

/**
 * @method
 * @name sbm_searchList_submitdone
 * @description searchList 통신 후처리
 * @param {Object} e e
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sbm_searchList_submitdone = async function (e) {
    if (e.responseStatusCode === 200) {
        if (scwin.vBndListProcsTpCd === '1' || scwin.vBndListProcsTpCd === '2') {
            scwin.rowPos(dlt_searchList, scwin.vRowPos);
        }

        let row = dlt_searchList.getRowPosition();
        if (row > -1) {
            scwin.vBndApplId = dlt_searchList.getCellData(row, "bndApplId");
            scwin.vProcsStatCd = dlt_searchList.getCellData(row, "procsStatCd");
            await scwin.dtlSync();
        }

        if (scwin.vBndListProcsTpCd === '1') {
            grd_ApplList.setFocusedCell(scwin.vRowPos, "bndApplId", false);
        } else {
            grd_AcptList.setFocusedCell(scwin.vRowPos, "bndApplId", false);
            for (let i = 0; i < dlt_searchList.getRowCount(); i++) {
                if (dlt_searchList.getDataRow(i).procsStat === '처리완료' &&
                    (dlt_searchList.getDataRow(i).teamleaderConfrmDd !== "undefined" && dlt_searchList.getDataRow(i).teamleaderConfrmDd !== '-' && dlt_searchList.getDataRow(i).teamleaderConfrmDd !== '')) { // 처리완료만 팀장확인 대상임
                    grd_AcptList.setCellDisabled(i, "CHK", true);
                }
            }
        }

    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
}

/**
 * @method
 * @name dtlSync
 * @description 그리드 선택 시 상세내역을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dtlSync = async function () {
    dma_search.set('vBndApplId', scwin.vBndApplId); // 채권신청ID
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd); // 채권처리구분(1:신청,2:접수)

    const sbmOptions = {
        id: "sbm_detail",
        action: scwin.fnDtlSyncUrl,
        method: "get",
        ref: "dma_search=body",
        target: "dma_bndIsu=body.bndIsu,dlt_bndCredit=body.bndCredit,dlt_bndSplitRedmpt=body.bndSplitRedmpt,dlt_bndUdwrtInst=body.bndUdwrtInst,dlt_bndPrincintInfo=body.bndPrincintInfo,dlt_bndOptionCall=body.bndOptionCall,dlt_bndOptionPut=body.bndOptionPut,dlt_bndChgInt=body.bndChgInt,dlt_bndSecutizAsst=body.bndSecutizAsst,dlt_bndStockRelExecprcAdj=body.bndStockRelExecprcAdj",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    dma_bndCoupnRtAndIsurPrc.setJSON(res.body.bndCoupnrtIsurprc.length > 0 ? res.body.bndCoupnrtIsurprc[0] : "");
};

/**
 * @method
 * @name sbm_detail_submitdone
 * @description detail 통신 후처리
 * @param {Object} e e
 * @returns {void}
 * @hidden N
 */
scwin.sbm_detail_submitdone = function (e) {
    if (e.responseStatusCode === 200) {
        scwin.vRowCount = dma_bndIsu.getCount();

        // 버튼설정
        scwin.setBtn();

        // 물가연동채구분
        if (dma_bndIsu.get('isurCd') === 'GB035') {
            cmb_InfllnkYn.setDisabled(false);
            edt_IsuDdRefIdx.setDisabled(false);
        } else {
            cmb_InfllnkYn.setDisabled(true);
            edt_IsuDdRefIdx.setDisabled(true);
        }

        // SRI채권구분 + 신청일 때만
        if (scwin.vBndListProcsTpCd === "1") {
            if (txb_sriBndTpCd.getValue() === '1') {
                txb_UnqIsuNm.setValue("(녹)");
                txb_UnqIsuEngNm.setValue("(G)");
            } else if (txb_sriBndTpCd.getValue() === '2') {
                txb_UnqIsuNm.setValue("(사)");
                txb_UnqIsuEngNm.setValue("(S)");
            } else if (txb_sriBndTpCd.getValue() === '3') {
                txb_UnqIsuNm.setValue("(지)");
                txb_UnqIsuEngNm.setValue("(T)");
            } else if (txb_sriBndTpCd.getValue() === '4') {
                txb_UnqIsuNm.setValue("(연)");
                txb_UnqIsuEngNm.setValue("(L)");
            }
        }

        // 물가연동채구분
        if (txb_sriBndRcptYn.getValue() === 'Y') {
            $c.win.alert("처리중인 ESG채권등록 신청건이 존재합니다.");
        }

        // 한글금액표기
        txb_AmtHan.setValue($c.num.numberToKor(dma_bndIsu.get('listAmt'), "원"));

        // 금액여분적용
        // scwin.setMargin();

        if (scwin.vRowCount === -1) return;
        let lbl = "";
        if (dma_bndIsu.get('stdCd') !== '') {
            let isuNm = dma_bndIsu.get('stdRefDtl');
            lbl = "신청내역" + isuNm;
            txb_Dtl1.setValue(lbl);
            txb_Dtl.hide();
            txb_Dtl1.show('');
        } else {
            txb_Dtl1.hide();
            txb_Dtl.show('');
        }

        // 신용등급 SF
        if (scwin.vBndListProcsTpCd !== '1' &&
            cmb_AsstSecutizTpCd.getValue() === '') {
            cmb_SfValuYn1.setValue('');
