        } // 시설
        if (dma_bndIsu.get("refundFndChgYn") === 'Y') {
            edt_RefundFnd.setStyle('backgroundColor', "#51F628");
        } else {
            edt_RefundFnd.setStyle('backgroundColor', "#FFFFFF");
