scwin.splitRedmptDdAutoCreate = async function () {
    dma_bndAutoCreate.setEmptyValue();

    dma_bndAutoCreate.set('vBndApplId', scwin.vBndApplId); // 채권신청ID
    dma_bndAutoCreate.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd); // 채권처리구분(1:신청,2:접수)

    let vFstSplitRedmptDd = edt_FstSplitRedmptDd.getValue();
    let vSplitRedmptCycle = edt_SplitRedmptCycle.getValue();
    let vSplitRedmptMmendTpCd = cmb_SplitRedmptMmendTpCd.getValue();
    let vEquivRedmptVal = edt_EquivRedmptVal.getValue();
    let vSplitRedmptCnt = edt_SplitRedmptCnt.getValue();

    dma_bndAutoCreate.set('vFstSplitRedmptDd', vFstSplitRedmptDd); // 최초분할상환일자
    dma_bndAutoCreate.set('vSplitRedmptCycle', vSplitRedmptCycle); // 분할상환주기
    dma_bndAutoCreate.set('vSplitRedmptMmendTpCd', vSplitRedmptMmendTpCd); // 분할상환월말구분코드
    dma_bndAutoCreate.set('vEquivRedmptVal', vEquivRedmptVal); // 균등상환액
    dma_bndAutoCreate.set('vSplitRedmptCnt', vSplitRedmptCnt); // 분할상환횟수

    const sbmOptions = {
        id: "sbm_splitRedmptDdAutoCreate",
        action: "/api/bonds/bndCommon/splitRedmpt-autoCreate",
        method: "get",
        ref: "dma_bndAutoCreate",
        target: "dlt_bndSplitRedmpt=body",
        // gridview: "grd_ApplList,grd_AcptList",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_splitRedmptDdAutoCreate_submitdone(sbmRtn);
};

