 */
scwin.sbm_chgIntRtAutoInput_submitdone = function (e) {
    if (e.responseStatusCode === 200) {
        if (dlt_bndChgInt.getCellData(0, 'intRtAlert') === 'Y') {
            $c.win.alert('변동금리 이자지급일에 유효하지 않은 일자가 포함되어 있습니다.<br/>최초이자지급일 또는 이자/월말 구분을 확인하여 주시기 바랍니다.');
        }
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

