/**
 * @method
 * @name checkEach
 * @description 개별 체크한다.
 * @returns {Promise<*>}
 * @hidden N
 */
scwin.checkEach = async function () {
    let msg = "";
    // SRI채권 고유명 체크
    // if (! window.confirm('표면이자율이 미확정입니다.<br/>그래도 처리하시겠습니까?')) return 1;
    if (txb_sriBndTpCd.getValue() === '1') {
        // alert(txb_UnqIsuNm.value);
        if (txb_UnqIsuNm.getValue().indexOf("(녹)") === -1) {
            if (await $c.win.confirm("ESG채권(녹색채권)으로 등록된 채권입니다.<br/><br/>한글고유명에 '(녹)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(G)") === -1) {
            if (await $c.win.confirm("ESG채권(녹색채권)으로 등록된 채권입니다.<br/><br/>영문고유명에 '(G)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() === '2') {
        if (txb_UnqIsuNm.getValue().indexOf("(사)") === -1) {
            if (await $c.win.confirm("ESG채권(사회적채권)으로 등록된 채권입니다.<br/><br/>한글고유명에 '(사)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(S)") === -1) {
            if (await $c.win.confirm("ESG채권(사회적채권)으로 등록된 채권입니다.<br/><br/>영문고유명에 '(S)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() === '3') {
        if (txb_UnqIsuNm.getValue().indexOf("(지)") === -1) {
            if (await $c.win.confirm("ESG채권(지속가능채권)으로 등록된 채권입니다.<br/><br/>한글고유명에 '(지)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(T)") === -1) {
            if (await $c.win.confirm("ESG채권(지속가능채권)으로 등록된 채권입니다.<br/><br/>영문고유명에 '(T)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
    } else if (txb_sriBndTpCd.getValue() === '4') {
        if (txb_UnqIsuNm.getValue().indexOf("(연)") === -1) {
            if (await $c.win.confirm("ESG채권(지속가능연계채권)으로 등록된 채권입니다.<br/><br/>한글고유명에 '(연)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
        if (txb_UnqIsuEngNm.getValue().indexOf("(L)") === -1) {
            if (await $c.win.confirm("ESG채권(지속가능연계채권)으로 등록된 채권입니다.<br/><br/>영문고유명에 '(L)' 글자가 포함되어있지 않습니다.<br/><br/>그래도 처리하시겠습니까?")) return 1;
        }
    }

    // 상장일이 발행일보다 빠른 경우 체크
    if (dma_bndIsu.get("listDd") < dma_bndIsu.get("isuDd")) {
        if (await $c.win.confirm('상장일이 발행일 이전입니다.<br/>그래도 처리하시겠습니까?')) return 1;
    }

    // 수정 or 처리완료
    if (scwin.processGp === '3' || scwin.processGp === '4') {
        // 마이너스 금리 체크 (접수시는 값변경이 안됨)  수정 및 처리완료 시에만 체크하도록 수정
        if (await scwin.minusGumriCheck() > 0) return 1; // JACKAL_191129

        // 상환방법: 영구채 선택시 상환일: 9999-12-31 이여야함.
        if (cmb_RedmptMethdTpCd.getValue() === "3" && edt_RedmptDd.getValue() !== "99991231") {
            await $c.win.alert("상환방법이 영구채 일 경우 상환일은 반드시 [9999-12-31]이여야 합니다.");
            edt_RedmptDd.focus();
            return 1;
        }
        // 상환일: 9999-12-31 선택시 상환방법: 영구채 이여야함.
        if (edt_RedmptDd.getValue() === "99991231" && cmb_RedmptMethdTpCd.getValue() !== "3") {
            await $c.win.alert("상환일이 [9999-12-31] 일 경우 상환방법은 반드시 영구채이여야 합니다.");
            cmb_RedmptMethdTpCd.focus();
            return 1;
        }
        if (cmb_RedmptMethdTpCd.getValue() === "3") {
            // 상환방법: 영구채 선택시 비정기 선택해야 함. JACKAL_190509
            // if (getObjectValue(cmb_RedmptMethdTpCd) == "3" )
            // {
            //    let cd = getObjectValue(cmb_IntDecsnRegulYn);
            //    // 금리결정 정기이면
            //    if(cd == 'Y')
            //    {
            //        alert("상환방법이 영구채 일 경우 변동금리 탭화면의 금리결정정기여부를 비정기로 선택하여야 합니다.");
            //        return 1;
            //    }
            // }

            if (await $c.win.confirm("영구채로 처리하시겠습니까?")) {
                return 1;
            } else {
                return false;
            }
        }

        // 소액채권 표준코드와 상장시 표면이자율이 상이한지 체크 JACKAL_20.01.31
        // dts_CheckCmData.SyncLoad = true;
        dma_CheckCmData.set('vStdCd', txb_StdCd.getValue());

        const sbmOptions = {
            id: "sbm_checkCmData",
            action: "/api/bonds/bndNew/corpBncoupnrtStdcd-chk",
            method: "get",
            ref: "dma_CheckCmData=body",
            target: "dma_CheckCmDataResult=body",
            // gridview: "grd_List1,grd_List2",
            // submitDoneHandler: scwin.sbm_checkCmData_submitdone, isProcessMsg: false
        };

        await $c.sbm.executeDynamic(sbmOptions);

        if (dma_CheckCmDataResult.getCount() > 0) {
            let cnt = dma_CheckCmDataResult.get('coupnRt');
            if (cnt !== dma_bndIsu.get("coupnRt")) {
                await $c.win.alert("표면이자율이 표준코드부여 시와 다릅니다.<br/>" + "관련 담당자에게 반드시 연락바랍니다.<br/>" + "연락 부재시 신고시장수익률 장애가 발생합니다.<br/>" + "[연락처]<br/>" + "KRX IT관리부 정보시스템팀 백윤경 과장(9875)<br/>" + "KRX IT관리부 증권시스템팀 김승한(9193)<br/>" + "코스콤 시장업무부 채권RDS 이승규 차장(676-8215)<br/>" + "코스콤 Check 송기성 과장(767-8621)");
                return 0;
            }
        }
    }

    // 처리완료 시 체크
    if (scwin.processGp === '3') {
        // 표면이자율 체크
        if (dma_bndIsu.get("coupnRtFinalYn") === '') {
            await $c.win.alert("표면이자율 확정여부를 선택하십시오.");
            return 1;
        } else if (dma_bndIsu.get("coupnRtFinalYn") === 'Y' &&
            dma_bndIsu.get("coupnRt") === '') {
            await $c.win.alert("표면이자율 확정시에는 표면이자율을 입력하십시오.");
            return 1;
        } else if (dma_bndIsu.get("coupnRtFinalYn") === 'N' &&
            dma_bndIsu.get("coupnRt") !== '') {
            if (await $c.win.confirm('표면이자율이 미확정입니다.<br/>그래도 처리하시겠습니까?')) return 1;
        }
    }

    // 상환방법: 영구채 선택시 휴무관련(원금) : 해당없음 선택이 원칙이나 선택사항이므로 경고문구만 띄운다.
    if (cmb_RedmptMethdTpCd.getValue() === "3" && cmb_BkHoldyPrincPayDdDecsnCd.getValue() !== "") {
        if (await $c.win.confirm("상환방법이 '영구채'이며 휴무관련(원금)이 선택되었습니다.<br/>그래도 처리하시겠습니까?")) {
            return 1;
        } else {
            return 0;
        }
    }

    // 이미 접수중인지 체크
    if (scwin.vBndListProcsTpCd === '1' && txb_StdCd.getValue() !== '') {
        let param = {
            vStdCd: txb_StdCd.getValue()
        }
        let url = "/api/bonds/bndNew/newListAcpt-chk"

        await $c.bns.searchBns(scwin.screnId, "dlt_CheckCmDataResult", url, param);

        if (dlt_CheckCmDataResult.getRowCount() > 0) {
            let id = dlt_CheckCmDataResult.getCellData(0, 'BND_APPL_ID');
            let dd = dlt_CheckCmDataResult.getCellData(0, 'STRT_DD');

            // TODO == 표준코드 중복으로 테스트를 위해 막아놓음
            if (dlt_CheckCmDataResult.getCellData(0, 'APPL_YN') === 'Y') {
                await $c.win.alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 시장조치되었습니다.");
                return 1;
            } else {
                await $c.win.alert("이미 접수번호 " + id + " : 적용일 " + dd + "로 처리중이므로 접수가 불가능합니다.");
                return 1;
            }
        }
    }
    if (scwin.vBndListProcsTpCd === '2') {
        // 신용기관체크
        let creditMsg = '신용평가기관을 선택하지 않으셨습니다.';
        let creditMsg1 = '신용등급을 선택하지 않으셨습니다.';
        if (cmb_CreditValuInstCd1.getValue() === '' && cmb_ByinstCreditValuGrd1.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd1.focus();
            return 1;
        } else if (cmb_CreditValuInstCd1.getValue() !== '' && cmb_ByinstCreditValuGrd1.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd1.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd2.getValue() === '' && cmb_ByinstCreditValuGrd2.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd2.focus();
            return 1;
        } else if (cmb_CreditValuInstCd2.getValue() !== '' && cmb_ByinstCreditValuGrd2.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd2.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd3.getValue() === '' && cmb_ByinstCreditValuGrd3.getValue() !== '') {
            $c.win.alert(creditMsg);
            cmb_CreditValuInstCd3.focus();
            return 1;
        } else if (cmb_CreditValuInstCd3.getValue() !== '' && cmb_ByinstCreditValuGrd3.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd3.focus();
            return 1;
        }
        if (cmb_CreditValuInstCd4.getValue() === '' && cmb_ByinstCreditValuGrd4.getValue() !== '') {
            await $c.win.alert(creditMsg);
            cmb_CreditValuInstCd4.focus();
            return 1;
        } else if (cmb_CreditValuInstCd4.getValue() !== '' && cmb_ByinstCreditValuGrd4.getValue() === '') {
            await $c.win.alert(creditMsg1);
            cmb_ByinstCreditValuGrd4.focus();
            return 1;
        }

        // 발행용도 총계 체크
        let listAmt = edt_ListAmt.getValue();
        if (edt_EqmtFnd.getValue() !== '' || edt_RefundFnd.getValue() !== '' || edt_OperFnd.getValue() !== '' || edt_MiscFnd.getValue() !== '') {
            let eqmtAmt = edt_EqmtFnd.getValue();
            if (eqmtAmt === '') eqmtAmt = 0;
            let refundAmt = edt_RefundFnd.getValue();
            if (refundAmt === '') refundAmt = 0;
            let operAmt = edt_OperFnd.getValue();
            if (operAmt === '') operAmt = 0;
            let miscAmt = edt_MiscFnd.getValue();
            if (miscAmt === '') miscAmt = 0;
            let fndAmt = parseInt(eqmtAmt) + parseInt(refundAmt) + parseInt(operAmt) + parseInt(miscAmt);
            if (Number(listAmt) !== fndAmt) {
                await $c.win.alert('발행용도 금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(1);
                if (edt_EqmtFnd.getValue() !== '') {
                    edt_EqmtFnd.focus();
                    return 1;
                } else if (edt_RefundFnd.getValue() !== '') {
                    edt_RefundFnd.focus();
                    return 1;
                } else if (edt_OperFnd.getValue() !== '') {
                    edt_OperFnd.focus();
                    return 1;
                } else if (edt_MiscFnd.getValue() !== '') {
                    edt_MiscFnd.focus();
                    return 1;
                }
            }
        }

        // 인수기관체크
        let isHas = false;
        let udwrAmtMsg = '인수기관 금액을 입력하십시오.';
        let udwrInstMsg = '인수기관을 선택 하십시오.';
        let udwrt1 = cmb_BndUdwrtInstCd1.getValue();
        let udwrt2 = cmb_BndUdwrtInstCd2.getValue();
        let udwrt3 = cmb_BndUdwrtInstCd3.getValue();
        let udwrt4 = cmb_BndUdwrtInstCd4.getValue();
        let udwrt1Amt = 0;
        let udwrt2Amt = 0;
        let udwrt3Amt = 0;
        let udwrt4Amt = 0;
        let udwrt5Amt = 0;
        if (udwrt1 !== '') {
            udwrt1Amt = edt_UdwrtAmt1.getValue();
            if (udwrt2 === udwrt1) {
                isHas = true;
            } else if (udwrt3 === udwrt1) {
                isHas = true;
            } else if (udwrt4 === udwrt1) {
                isHas = true;
            }
            if (edt_UdwrtAmt1.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt1.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt1.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd1.focus();
                return 1;
            }
        }
        if (udwrt2 !== '') {
            udwrt2Amt = edt_UdwrtAmt2.getValue();
            if (udwrt1 === udwrt2) {
                isHas = true;
            } else if (udwrt3 === udwrt2) {
                isHas = true;
            } else if (udwrt4 === udwrt2) {
                isHas = true;
            }
            if (edt_UdwrtAmt2.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt2.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt2.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd2.focus();
                return 1;
            }
        }
        if (udwrt3 !== '') {
            udwrt3Amt = edt_UdwrtAmt3.getValue();
            if (udwrt1 === udwrt3) {
                isHas = true;
            } else if (udwrt2 === udwrt3) {
                isHas = true;
            } else if (udwrt4 === udwrt3) {
                isHas = true;
            }
            if (edt_UdwrtAmt3.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt3.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt3.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd3.focus();
                return 1;
            }
        }
        if (udwrt4 !== '') {
            udwrt4Amt = edt_UdwrtAmt4.getValue();
            if (udwrt1 === udwrt4) {
                isHas = true;
            } else if (udwrt2 === udwrt4) {
                isHas = true;
            } else if (udwrt3 === udwrt4) {
                isHas = true;
            }
            if (edt_UdwrtAmt4.getValue() === '') {
                await $c.win.alert(udwrAmtMsg);
                edt_UdwrtAmt4.focus();
                return 1;
            }
        } else {
            if (edt_UdwrtAmt4.getValue() !== '') {
                await $c.win.alert(udwrInstMsg);
                cmb_BndUdwrtInstCd4.focus();
                return 1;
            }
        }
        if (isHas) {
            await $c.win.alert('동일한 인수기관을 선택 하셨습니다. 인수기관을 확인하여 주십시요.');
            return 1;
        }

        // 인수금액 총계 체크
        udwrt5Amt = edt_UdwrtAmt5.getValue();
        if (udwrt5Amt === '') udwrt5Amt = 0;
        let udwrtAmt = parseInt(udwrt1Amt) + parseInt(udwrt2Amt) + parseInt(udwrt3Amt) + parseInt(udwrt4Amt) + parseInt(udwrt5Amt);
        if (udwrtAmt > 0) {
            if (Number(listAmt) !== udwrtAmt) {
                await $c.win.alert('인수금액 총계를 확인하십시오.');
                tab_Detail.setSelectedTabIndex(2);
                if (edt_UdwrtAmt1.getValue() !== '') {
                    edt_UdwrtAmt1.focus();
                    return 1;
                } else if (edt_UdwrtAmt2.getValue() !== '') {
                    edt_UdwrtAmt2.focus();
                    return 1;
                } else if (edt_UdwrtAmt3.getValue() !== '') {
                    edt_UdwrtAmt3.focus();
                    return 1;
                } else if (edt_UdwrtAmt4.getValue() !== '') {
                    edt_UdwrtAmt4.focus();
                    return 1;
                } else if (edt_UdwrtAmt5.getValue() !== '') {
                    edt_UdwrtAmt5.focus();
                    return 1;
                }
            }
        }

        // 변동금리탭 이자율변경 정보
        let rowCnt = dlt_bndChgInt.getRowCount();
        for (let idx = 0; idx < rowCnt; idx++) {
            if (dlt_bndChgInt.getCellData(idx, 'intRtChgDd').length !== 8) {
                await $c.win.alert('변동금리탭 이자율결정 기준일 정보를 확인하여 주십시요.');
                dlt_bndChgInt.setRowPosition(idx, 0);
                return 1;
            }
        }

        // 옵션탭 Call
        if (scwin.chkCall() > 0) return 1;

        // 옵션탭 Put
        if (scwin.chkPut() > 0) return 1;

        // 분할상환체크
        rowCnt = dlt_bndSplitRedmpt.getRowCount();
        for (let idx = 0; idx < rowCnt; idx++) {
            if (dlt_bndSplitRedmpt.getCellData(idx, 'intPayDd').length !== 8) {
                await $c.win.alert('분할상환탭 불균등 정보를 확인하여 주십시요.');
                dlt_bndSplitRedmpt.setRowPosition(idx, 0);
                return 1;
            }
        }

        // 원리금정보
        rowCnt = dlt_bndPrincintInfo.getRowCount();
        for (let idx = 0; idx < rowCnt; idx++) {
            if (dlt_bndPrincintInfo.getCellData(idx, 'intPayDd').length !== 8) {
                await $c.win.alert('원리금탭 정보를 확인하여 주십시요.');
                dlt_bndPrincintInfo.setRowPosition(idx, 0);
                return 1;
            }
        }

        // 분리형BW여부가 체크가 안된 경우만 메세지 확인함. jackal_181210
        if (chk_DetachBwYn.getValue() !== 'Y') {
            if (cmb_StkRelCorpbndRghtTpCd.getValue() !== '' && cmb_NusualBndTpCd.getValue() !== '2') {
                msg = "" + "특이채권유형이 " + $c.stf.getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "<br/>주식관련탭의 권리구분이 [" + $c.stf.getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "<br/>" + "<br/>주식관련탭의 권리구분은 주식관련사채일때만 입력가능한 항목입니다." + "<br/>그래도 작업을 계속하시겠습니까?";
                if (await $c.win.confirm(msg)) return 1;
            }
        }

        // ELB등
        if (cmb_NusualBndTpCd.getValue() === '3' || cmb_NusualBndTpCd.getValue() === '4') {
            if (edt_PrincGrtRt.getValue() === '') {
                await $c.win.alert("원금보장율을 입력하십시오.");
                return 1;
            }
        } else if (edt_PrincGrtRt.getValue() === '') {
            if (cmb_NusualBndTpCd.getValue() === '3' || cmb_NusualBndTpCd.getValue() === '4') {
                await $c.win.alert("ELB등 탭은 ELS/DLS채권시에만 입력합니다. 특이채권유형을 확인바랍니다.");
                return 1;
            }
        }
        if (dma_bndIsu.get("intPayMethdCd") === '' ||
            dma_bndIsu.get("intPayMethdCd").substring(0, 1) === '1') {
            if (dma_bndIsu.get("intRtDecsnMiscBasIntNm") !== '') {
                await $c.win.alert("변동금리탭은 변동금리시에만 입력합니다. 이자지급방법을 확인바랍니다.");
                return 1;
            }
        }
        if (dma_bndIsu.get("imbdoptCorpbndCd") === '' &&
            (dlt_bndOptionCall.getRowCount() > 0 || dlt_bndOptionPut.getRowCount() > 0)) {
            await $c.win.alert("CALL/PUT 탭은 옵션일 경우에만 입력합니다. 옵션구분을 확인바랍니다.");
            return 1;
        }
        if (dma_bndIsu.get("asstSecutizTpCd") === '' &&
            dma_bndIsu.get("secutizAdmInstCd").substring(0, 1) === '1') {
            await $c.win.alert("유동화탭은 유동화 채권일 경우에만 입력합니다. 유동화채권 인지 확인바랍니다.");
            return 1;
        }
        if (!$c.stf.checkMaxLength(txb_IntRtDecsnMiscBasIntNm, 20, '기타기준금리')) return 1;
        if (!$c.stf.checkMaxLength(txb_NusualIsuCondContn, 60, '특이발행조건(외부용)')) return 1;
        if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '기타참고사항(내부용)')) return 1;
        if (!$c.stf.checkMaxLength(txb_UlyContn, 100, '기초자산상세내용')) return 1;
        if (!$c.stf.checkMaxLength(txb_ElsCondContn1, 100, '조건내용1')) return 1;
        if (!$c.stf.checkMaxLength(txb_ElsCondContn2, 100, '조건내용2')) return 1;

        // jackal_16.10.11  call put 사유 길이 체크 추가
        if (!$c.stf.checkMaxLength(txb_CallExerRsn, 50, '콜 사유')) return 1;
        if (!$c.stf.checkMaxLength(txb_PutExerRsn, 50, '풋 사유')) return 1;

        // 국고채만 스트립미분리잔액 입력가능
        if (scwin.vMktactCd === '111' &&
            cmb_InfllnkYn.getValue() !== 'Y' &&
            dma_bndIsu.get("isuNm").indexOf("변동") === -1) {
            if (dma_bndIsu.get("isurCd") === 'GB035' &&
                cmb_BndStripTpCd.getValue() === '1') {
                let num_iss_dt = edt_IsuDd.getValue();
                let expr_term = (edt_RedmptDd.getValue() - edt_IsuDd.getValue()) / 10000;

                // 2006년 이후 발행된 만기 5년이상 국고채권만 미분류 잔액이 존재
                // jackal_150714 3년물이상으로 변경되었는데 여태 수정이 안되어 있었슴. expr_term 5을 3을 수정
                if (num_iss_dt >= 20060101 && expr_term >= 3) {
                    await $c.win.alert('스트립미분리잔액을 상장금액으로 자동설정합니다.');
                    edt_StripNsprtBal.setValue(edt_ListAmt.getValue());
                } else {
                    edt_StripNsprtBal.setValue('');
                }
            }
        } else {
            edt_StripNsprtBal.setValue('');
        }

        // 환율적용 발행금액,상장금액 체크
        if (cmb_CurrTpCd.getValue() !== '' &&
            cmb_CurrTpCd.getValue() !== '1') {
            let isuAmt = edt_IsuAmt.getValue();
            let listAmt = edt_ListAmt.getValue();
            if (isuAmt === '') isuAmt = 0;
            if (listAmt === '') listAmt = 0;
            let exchrt = $c.bns.searchExchrt(scwin.screnId, dts_CheckExa, cmb_CurrTpCd.getValue(), '1'); // TODO Stage2: pcc bns_common.searchExchrt 는 Gauce 잔재(SyncLoad·searchBns 5인자)·dts_CheckExa 미선언 — 업무공통 전환 후 재대조
            isuAmt = isuAmt * exchrt;
            listAmt = listAmt * exchrt;

            // 메시지 추가 발행금액이 상장금액보다 크거나 같아야 합니다.
            if (parseInt(isuAmt) < parseInt(listAmt)) {
                await $c.win.alert("발행금액은 상장금액보다 크거나 같아야 합니다.");
                return 1;
            }
            if (isuAmt <= 100000000) {
                await $c.win.alert("발행금액이 1억원 이하입니다.");
            } else if (isuAmt >= 1000000000000) {
                await $c.win.alert("발행금액이 1조원 이상입니다.");
            }
            if (listAmt <= 100000000) {
                await $c.win.alert("상장금액이 1억원 이하입니다.");
            } else if (listAmt >= 1000000000000) {
                await $c.win.alert("상장금액이 1조원 이상입니다.");
            }
        }

        // 분리형BW여부가 체크는 특이채권유형이 일반채권인 경우만 체크가능 jackal_181210
        if (chk_DetachBwYn.getValue() === 'Y') {
            if (cmb_NusualBndTpCd.getValue() !== '1') {
                msg = "" + "분리형BW가 체크된 경우 특이채권유형이 [1 일반채권] 이어야 합니다." + "<br/>특이채권유형이 [" + $c.stf.getComboTextValue(cmb_NusualBndTpCd) + "]로 입력되어 있습니다.";
                await $c.win.alert(msg);
                return 1;
            }
        }

        //  분리형BW여부가 체크되어 있스면 권리구분이 21 이어야 하고 jackal_181210
        if (chk_DetachBwYn.getValue() === 'Y') {
            // 주식관련 권리구분 21 setting
            if (cmb_StkRelCorpbndRghtTpCd.getValue() !== '21') {
                msg = "" + "분리형BW가 체크된 경우 주식관련탭의 권리구분이 [21 신주인수권(분리형)] 이어야 합니다. " + "<br/>주식관련탭의 권리구분이 [" + $c.stf.getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다.";
                await $c.win.alert(msg);
                return 1;
            }
        }

        // 더불어 특이채권유형이 2(주권관련채권) 이면 21은 선택 못하게 해야 함. jackal_181210
        if (cmb_NusualBndTpCd.getValue() === '2') {
            if (cmb_StkRelCorpbndRghtTpCd.getValue() === '21') {
                msg = "" + "특이채권유형이 " + $c.stf.getComboTextValue(cmb_NusualBndTpCd) + " 인데 " + "<br/>주식관련탭의 권리구분이 [" + $c.stf.getComboTextValue(cmb_StkRelCorpbndRghtTpCd) + "]로 입력되어 있습니다." + "<br/>" + "<br/>이 권리구분은 일반채권 분리형BW가 체크 되었을때만 입력가능한 항목입니다.";
                await $c.win.alert(msg);
                return 1;
            }
        }

        // 이자지급방법이 변동금리형이면
        if (cmb_IntPayMethdCd.getValue() > 20) {
            // 금리결정기준일 1~10 일까지 만 입력 체크   JACKAL_190509
            let vIntDecsnBasDys = edt_IntDecsnBasDys.getValue();
            if (vIntDecsnBasDys !== '' && (vIntDecsnBasDys > 10 || vIntDecsnBasDys < 1)) {
                if (await $c.win.confirm('변동금리 탭의 이자지급기준일로부터 금리결정기준일은 1 ~ 10 일전 까지만 선택가능합니다.<br/>그래도 처리하시겠습니까?')) return 1;
            }
        }
    }
    return 0;
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 및 수정을 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function () {
    // 종목정보체크
    if (await $c.bns.checkNewListIsuInfo(dma_bndIsu) > 0) return;   // // 업무공통 확인필요
    if (await scwin.checkEach() > 0) return;
    if (scwin.processGp === '4') {
        if (await $c.bns.checkModAndRet(scwin.vBndApplId) > 0) return;
    }
    // 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if (await $c.bns.chkBndClssAndIsur(scwin.screnId, dma_bndIsu, scwin.vMktactCd) > 0) return; // // 업무공통 확인필요

    // //고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (await $c.bns.addCheck(dma_bndIsu) > 0) return;  // // 업무공통 확인필요

    // //수수료체크
    if (await $c.bns.checkFee('1', scwin.vBndApplId) > 0) return;
    // //처리완료,수정
    let hasAttachDoc = dma_bndIsu.get("hasAttachDoc");
    if (scwin.processGp === '4') {
        // if(! fn_EndConfirm(hasAttachDoc, '수정')) return;
        if (!await $c.bns.endConfirm1(scwin.screnId, dma_bndattachDocYnEnd, scwin.vBndApplId, scwin.vBndListProcsTpCd, '수정')) return; // // 업무공통 확인필요
    } else {
        // 적용일,매매일,마감일,채권마감 체크
        if (await $c.bns.checkCmData(edt_ListDd.getValue(), scwin.vBndApplId) > 0) return;
        // if(! fn_EndConfirm(hasAttachDoc, '처리완료')) return;
        if (!await $c.bns.endConfirm1(scwin.screnId, dma_bndattachDocYnEnd, scwin.vBndApplId, scwin.vBndListProcsTpCd, '처리완료')) return; // // 업무공통 확인필요
    }

    // 발행방법설정
    let ISU_METHD_INDIRECT = dma_bndIsu.get('isuMethdIndirect');
    let ISU_METHD_DIRECT = dma_bndIsu.get('isuMethdDirect');
    let ISU_METHD_PPBOND = dma_bndIsu.get('isuMethdPpbond');

    dma_bndIsu.set('bndIsuMethdCd', ISU_METHD_INDIRECT + "" + ISU_METHD_DIRECT + "" + ISU_METHD_PPBOND);

    // 분리형BW여부 설정 jackal_181210
    let DETACH_BW_YN = dma_bndIsu.get('detachBwYn');
    if (DETACH_BW_YN === '1') dma_bndIsu.set('detachBwYn', 'Y');
    else dma_bndIsu.set('detachBwYn', 'N');

    // 탭 데이터셋 설정
    scwin.setCreditData();
    scwin.setUdwrtInstData();
    scwin.setSecutizAsstData();
    scwin.setBasIntRtData();

    // 변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    // dts_IsuInfo.UseChangeInfo = "False";
    // dts_OptionCall.UseChangeInfo = "False";
    // dts_OptionPut.UseChangeInfo = "False";
    // dts_Princint.UseChangeInfo = "False";
    // dts_SplitRedmpt.UseChangeInfo = "False";
    // dts_ChgInt.UseChangeInfo = "False";
    // // 주식관련 행사가격 조정 JACKAL_190220
    // dts_StockRel.UseChangeInfo = "False";

    let url = "";
    if (scwin.processGp === '4') { // 수정
        url = scwin.fnModifyUrl;
    }
    else if (scwin.processGp === '3') { // 처리완료
        url = scwin.fnProcComplt;
    }

    dma_Param.set('bndApplId', scwin.vBndApplId);
    dma_Param.set('bndListProcsTpCd', scwin.vBndListProcsTpCd);
    dma_Param.set('strtDd', dma_bndIsu.get("listDd"));
    dma_Param.set('stdCd', dma_bndIsu.get("stdCd"));

    dma_bndIsu.set('coupnRtDecsnBasIntCd', cmb_CoupnRtDecsnBasIntCd.getValue());

    let dmaParam = dma_Param.getJSON();

    if (dmaParam.listChgBndApplId === "") {
        dmaParam.listChgBndApplId = [];
    }
    dma_Param.setJSON(dmaParam);

    const sbmOptions = {
        id: "sbm_modifyProcComplt",
        action: url,
        method: "post",
        ref: "dma_Param=dts_Param,dma_bndIsu=dts_IsuInfo,dlt_bndCredit=dts_Credit,dlt_bndUdwrtInst=dts_UdwrtInst,dma_bndCoupnRtAndIsurPrc=dts_CoupnRtAndIsurPrc,dlt_bndPrincintInfo=dts_Princint,dlt_bndOptionCall=dts_OptionCall,dlt_bndOptionPut=dts_OptionPut,dlt_bndChgInt=dts_ChgInt,dlt_bndSplitRedmpt=dts_SplitRedmpt,dlt_bndSecutizAsst=dts_SecutizAsst,dlt_bndStockRelExecprcAdj=dts_StockRel",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        await scwin.trs_Save_OnSuccess();
    } else {
        scwin.trs_Save_OnFail();
    }
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function () {

    // 테스트를 위해 임시로 넣어 놓음
    dma_bndIsu.set('redmptDd', $c.date.addDate(edt_ListDd.getValue(), 2));

    // 종목정보체크
    if (await $c.bns.checkNewListIsuInfo(dma_bndIsu) > 0) return; // // 업무공통 확인필요
    if (await scwin.checkEach() > 0) return;
    // 적용일,매매일,마감일,채권마감 체크
    if (await $c.bns.checkCmData(edt_ListDd.getValue(), scwin.vBndApplId) > 0) return;
    // 채권분류코드와 발행기관, 채권유형 등과 맞는지 체크한다.
    if (await $c.bns.chkBndClssAndIsur1(scwin.screnId, dma_bndIsu, scwin.vMktactCd) > 0) return;

    // 고객요건에의한 체크 추가. 2024-06-05 by김효준
    if (await $c.bns.addCheck(dma_bndIsu) > 0) return;

    // 접수
    // if(! fn_EndConfirm(hasAttachDoc, '접수')) return;
    if (! await $c.bns.endConfirm1(scwin.screnId, dma_bndattachDocYnEnd, scwin.vBndApplId, scwin.vBndListProcsTpCd, '접수')) return;

    // TODO == 수수료 팝업호출
    scwin.getParNewListFee();
    // let result = await $c.bns.popNewListFee(scwin.arrPar);
    // scwin.vRegYn = reuslt.regYn;

    // if (scwin.vRegYn != "Y") return;

    // 수수료팝업 작업 전으로 임시데이터 넣음
    dma_newListFee.set('bndApplId', scwin.vBndApplId);
    dma_newListFee.set('bndListProcsTpCd', scwin.vBndListProcsTpCd);
    dma_newListFee.set('feeGrpNm', 'test');

    dma_Param.set('bndApplId', scwin.vBndApplId);
    dma_Param.set('bndListProcsTpCd', scwin.vBndListProcsTpCd);
    dma_Param.set('strtDd', dma_bndIsu.get("listDd"));
    dma_bndIsu.set('coupnRtDecsnBasIntCd', cmb_CoupnRtDecsnBasIntCd.getValue());

    let dmaParam = dma_Param.getJSON();

    if (dmaParam.listChgBndApplId === "") {
        dmaParam.listChgBndApplId = [];
    }
    dma_Param.setJSON(dmaParam);

    const sbmOptions = {
        id: "sbm_acptList",
        action: scwin.fnAcptUrl,
        method: "post",
        // ref: "dma_Param=dts_Param,dma_bndIsu=dts_IsuInfo,dlt_bndCredit=dts_Credit,dlt_bndUdwrtInst=dts_UdwrtInst,dma_bndCoupnRtAndIsurPrc=dts_CoupnRtAndIsurPrc,dlt_bndPrincintInfo=dts_Princint,dlt_bndOptionCall=dts_OptionCall,dlt_bndOptionPut=dts_OptionPut,dlt_bndChgInt=dts_ChgInt,dlt_bndSplitRedmpt=dts_SplitRedmpt,dlt_bndSecutizAsst=dts_SecutizAsst,dlt_bndStockRelExecprcAdj=dts_StockRel",
        ref: "dma_Param=dts_Param,dma_bndIsu=dts_IsuInfo,dma_newListFee=dts_NewListFee",
        isProcessMsg: false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success) {
        await scwin.trs_Save_OnSuccess();
    } else {
        scwin.trs_Save_OnFail();
    }
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀다운로드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownload = async function () {

    // showload.show(''); // showload.style.display = "";

    // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리
    btn_Excel.setDisabled(true);

    dma_bndApplAndAcptExcel.set('vMktactCd', scwin.vMktactCd);
    dma_bndApplAndAcptExcel.set('vBndListProcsTpCd', scwin.vBndListProcsTpCd);

    const sbmOptions = {
        id: "sbm_bndApplAndAcptExcel",
        action: scwin.fnExcelDownUrl,
        method: "get",
        ref: "dma_bndApplAndAcptExcel=body",
        target: "dlt_bndApplAndAcptExcel=body",
        // gridview: "grd_List1,grd_List2",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_bndApplAndAcptExcel_submitdone(sbmRtn);

    let fileNm = $c.session.getExcelDownPath() + $c.date.getServerDateTime() + "_국채 개별상장 접수내역.xls";
    $c.data.downloadGridViewExcel(grd_AcptList, fileNm);
};

